 "content": "def transform(grid):
    """Complete downward clue-coded vertical lines anchored by bottom-row 5s."""
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])
    for c in range(w):
        if grid[h - 1][c] != 5:
            continue
        clues = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        if not clues:
            continue
        # Extend the first clue to the top; between clues, the lower clue's
        # color fills the gap. Clue cells themselves remain unchanged.
        first_r, first_color = clues[0]
        for r in range(first_r):
            out[r][c] = first_color
        for (upper_r, _), (lower_r, lower_color) in zip(clues, clues[1:]):
            for r in range(upper_r + 1, lower_r):
                out[r][c] = lower_color
    return out
